package com.rpsbattle.tournament;
import com.rpsbattle.account.domain.*;import com.rpsbattle.account.repository.UserRepository;import com.rpsbattle.auth.*;import com.rpsbattle.tournament.domain.*;import com.rpsbattle.tournament.persistence.*;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import java.time.Instant;import java.util.*;import static org.assertj.core.api.Assertions.*;
@SpringBootTest class RegistrationFlowTest {
 @Autowired OwnedTournamentService owned;@Autowired UserRepository users;@Autowired TournamentRepository repository;
 User user(){var now=Instant.now();String name="human_"+UUID.randomUUID().toString().substring(0,8);return users.save(new User(UserId.random(),name,name+"@example.invalid","fixture",name,UserRole.USER,AccountStatus.ACTIVE,now,now,null,0));}
 @Test void organizerCannotRegisterAsHumanOrBotApproveHistoricalOwnSeatOrCheckIn(){
  var manager=user();var owner=AuthService.sessionAuthentication(manager);var t=owned.create(owner,"Owner does not compete",TournamentFormat.ROUND_ROBIN,"PUBLIC",true,4,null,null,ParticipantPolicy.HUMAN_OR_BOT);owned.openRegistration(owner,t.id);
  assertThatThrownBy(()->owned.registerHuman(owner,t.id,true)).hasMessage("ORGANIZER_CANNOT_PARTICIPATE");
  assertThatThrownBy(()->owned.register(owner,t.id,UUID.randomUUID().toString())).hasMessage("ORGANIZER_CANNOT_PARTICIPATE");
  var seat=new TournamentRegistration(UUID.randomUUID(),UUID.fromString(t.id),manager.id().value(),null,null,manager.displayName(),TournamentRegistration.Status.PENDING,Instant.now(),null,null);t.registrations.add(seat);
  assertThatThrownBy(()->owned.review(owner,t.id,seat.id().toString(),true)).hasMessage("ORGANIZER_CANNOT_PARTICIPATE");
  assertThat(t.participants).isEmpty();assertThat(t.registrations.getFirst().status()).isEqualTo(TournamentRegistration.Status.PENDING);
  assertThatThrownBy(()->owned.checkIn(owner,t.id,null)).hasMessage("ORGANIZER_CANNOT_PARTICIPATE");owned.review(owner,t.id,seat.id().toString(),false);
 }
 @Test void humanRegistrationIsAccountOwnedUniquePolicyBoundAndPersistsWithoutFakeBot(){var owner=AuthService.sessionAuthentication(user());var player=AuthService.sessionAuthentication(user());var other=AuthService.sessionAuthentication(user());var t=owned.create(owner,"Human registration",TournamentFormat.ROUND_ROBIN,"PUBLIC",true,2,null,null,ParticipantPolicy.HUMAN_ONLY);owned.openRegistration(owner,t.id);
  assertThatThrownBy(()->owned.registerHuman(player,t.id,false)).hasMessage("RULES_ACCEPTANCE_REQUIRED");assertThatThrownBy(()->owned.register(player,t.id,UUID.randomUUID().toString())).hasMessage("CONTROLLER_NOT_ALLOWED");owned.registerHuman(player,t.id,true);var r=t.registrations.getFirst();assertThat(r.botId()).isNull();assertThat(r.status()).isEqualTo(TournamentRegistration.Status.PENDING);assertThatThrownBy(()->owned.registerHuman(player,t.id,true)).hasMessage("DUPLICATE_PARTICIPANT");
  assertThatThrownBy(()->owned.review(other,t.id,r.id().toString(),true)).isInstanceOf(AuthException.class);assertThatThrownBy(()->owned.withdraw(other,t.id,r.id().toString())).isInstanceOf(AuthException.class);owned.review(owner,t.id,r.id().toString(),true);assertThat(t.participants.getFirst().botId()).isNull();
  var stored=repository.all().stream().filter(row->row.id().toString().equals(t.id)).findFirst().orElseThrow();assertThat(stored.participants().getFirst().botId()).isNull();assertThat(stored.details().participantPolicy()).isEqualTo(ParticipantPolicy.HUMAN_ONLY);
  owned.withdraw(player,t.id,r.id().toString());assertThat(t.participants).isEmpty();owned.registerHuman(player,t.id,true);assertThat(t.registrations.getFirst().id()).isEqualTo(r.id());
 }
 @Test void bestOfIsValidatedBeforeCreationAndPersistsWithRulesSnapshot(){var auth=AuthService.sessionAuthentication(user());assertThatThrownBy(()->owned.create(auth,"Invalid series",TournamentFormat.ROUND_ROBIN,"PUBLIC",false,2,null,null,ParticipantPolicy.HUMAN_ONLY,2)).hasMessage("INVALID_BEST_OF");var t=owned.create(auth,"BO5",TournamentFormat.ROUND_ROBIN,"PUBLIC",false,2,null,null,ParticipantPolicy.HUMAN_ONLY,5);assertThat(t.bestOf).isEqualTo(5);var stored=repository.all().stream().filter(row->row.id().toString().equals(t.id)).findFirst().orElseThrow();assertThat(stored.details().bestOf()).isEqualTo(5);}
 @Test void existingBotOnlyPolicyAndMixedHumanPolicyRemainDistinct(){var auth=AuthService.sessionAuthentication(user());var player=AuthService.sessionAuthentication(user());var legacy=owned.create(auth,"Legacy bot-only",TournamentFormat.ROUND_ROBIN,"PUBLIC");owned.openRegistration(auth,legacy.id);assertThatThrownBy(()->owned.registerHuman(player,legacy.id,true)).hasMessage("CONTROLLER_NOT_ALLOWED");var mixed=owned.create(auth,"Mixed policy",TournamentFormat.SINGLE_ELIMINATION,"PUBLIC",false,4,null,null,ParticipantPolicy.HUMAN_OR_BOT);owned.openRegistration(auth,mixed.id);owned.registerHuman(player,mixed.id,true);assertThat(mixed.registrations).hasSize(1);}
}
